<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $config = json_decode(file_get_contents(storage_path('app/pandu_config.json')), true); $sync = new \App\Services\GoogleFormsSyncService(); foreach ($config['forms'] as $f) { if ($f['slug'] == 'lemari-apd-workshop') { print_r($sync->getLiveResponses($f['id'], $f['slug'])->take(1)->toArray()); break; } }
